// Tests for earcutTriangles, the port of mapbox/earcut 3.0.2. The expected indices were
// produced by running the JavaScript (three.js r187's extras/lib/earcut.js) under node on the
// same inputs, so every case compares the indices exactly, in order.
#include <cmath>
#include <vector>

#include "../Curves/Earcut.h"
#include "Testing.h"

using namespace editor;

namespace {

std::vector<int> triangulate(const std::vector<double>& coordinates, const std::vector<int>& holeStarts) {
    return earcutTriangles(coordinates, holeStarts);
}

/// Twice the absolute area of the ring from corner `first` up to (not including) `last`.
double ringArea(const std::vector<double>& coordinates, int first, int last) {
    double sum = 0;
    for (int corner = first; corner < last; corner += 1) {
        int following = corner + 1 < last ? corner + 1 : first;
        sum += coordinates[2 * corner] * coordinates[2 * following + 1] - coordinates[2 * following] * coordinates[2 * corner + 1];
    }
    return std::fabs(sum) / 2;
}

double trianglesArea(const std::vector<double>& coordinates, const std::vector<int>& indices) {
    double sum = 0;
    for (size_t k = 0; k + 2 < indices.size(); k += 3) {
        const double* a = &coordinates[2 * static_cast<size_t>(indices[k])];
        const double* b = &coordinates[2 * static_cast<size_t>(indices[k + 1])];
        const double* c = &coordinates[2 * static_cast<size_t>(indices[k + 2])];
        sum += std::fabs((b[0] - a[0]) * (c[1] - a[1]) - (c[0] - a[0]) * (b[1] - a[1])) / 2;
    }
    return sum;
}

/// The polygon's area minus its holes' areas.
double polygonArea(const std::vector<double>& coordinates, const std::vector<int>& holeStarts) {
    int total = static_cast<int>(coordinates.size() / 2);
    int outerEnd = holeStarts.empty() ? total : holeStarts[0];
    double area = ringArea(coordinates, 0, outerEnd);
    for (size_t h = 0; h < holeStarts.size(); h += 1) {
        int holeEnd = h + 1 < holeStarts.size() ? holeStarts[h + 1] : total;
        area -= ringArea(coordinates, holeStarts[h], holeEnd);
    }
    return area;
}

}  // namespace


TEST(earcut_triangle) {
    std::vector<double> coordinates = {0.0, 0.0, 10.0, 0.0, 5.0, 8.0};
    std::vector<int> holeStarts = {};
    std::vector<int> expected = {1, 2, 0};
    EXPECT(triangulate(coordinates, holeStarts) == expected);
}


TEST(earcut_square) {
    std::vector<double> coordinates = {0.0, 0.0, 10.0, 0.0, 10.0, 10.0, 0.0, 10.0};
    std::vector<int> holeStarts = {};
    std::vector<int> expected = {2, 3, 0, 0, 1, 2};
    EXPECT(triangulate(coordinates, holeStarts) == expected);
}


TEST(earcut_squareWithHole) {
    std::vector<double> coordinates = {0.0, 0.0, 10.0, 0.0, 10.0, 10.0, 0.0, 10.0, 3.0, 3.0, 7.0, 3.0, 7.0, 7.0, 3.0, 7.0};
    std::vector<int> holeStarts = {4};
    std::vector<int> expected = {0, 4, 7, 5, 4, 0, 3, 0, 7, 5, 0, 1, 2, 3, 7, 6, 5, 1, 2, 7, 6, 6, 1, 2};
    EXPECT(triangulate(coordinates, holeStarts) == expected);
}


TEST(earcut_concaveL) {
    std::vector<double> coordinates = {0.0, 0.0, 6.0, 0.0, 6.0, 2.0, 2.0, 2.0, 2.0, 6.0, 0.0, 6.0};
    std::vector<int> holeStarts = {};
    std::vector<int> expected = {4, 5, 0, 0, 1, 2, 3, 4, 0, 0, 2, 3};
    EXPECT(triangulate(coordinates, holeStarts) == expected);
}


TEST(earcut_collinearEdge) {
    std::vector<double> coordinates = {0.0, 0.0, 2.0, 0.0, 4.0, 0.0, 6.0, 0.0, 6.0, 6.0, 0.0, 6.0};
    std::vector<int> holeStarts = {};
    std::vector<int> expected = {4, 5, 0, 2, 3, 4, 4, 0, 1, 1, 2, 4};
    EXPECT(triangulate(coordinates, holeStarts) == expected);
}


TEST(earcut_duplicateConsecutive) {
    std::vector<double> coordinates = {0.0, 0.0, 5.0, 0.0, 5.0, 0.0, 10.0, 0.0, 10.0, 10.0, 0.0, 10.0};
    std::vector<int> holeStarts = {};
    std::vector<int> expected = {4, 5, 0, 2, 3, 4, 2, 4, 0};
    EXPECT(triangulate(coordinates, holeStarts) == expected);
}


TEST(earcut_closedRing) {
    std::vector<double> coordinates = {0.0, 0.0, 10.0, 0.0, 10.0, 10.0, 0.0, 10.0, 0.0, 0.0};
    std::vector<int> holeStarts = {};
    std::vector<int> expected = {3, 0, 1, 1, 2, 3};
    EXPECT(triangulate(coordinates, holeStarts) == expected);
}


TEST(earcut_holeTouchingOuter) {
    std::vector<double> coordinates = {0.0, 0.0, 10.0, 0.0, 10.0, 10.0, 0.0, 10.0, 5.0, 0.0, 7.0, 3.0, 3.0, 3.0};
    std::vector<int> holeStarts = {4};
    std::vector<int> expected = {3, 0, 6, 4, 6, 0, 2, 3, 6, 2, 6, 5, 1, 2, 5, 1, 5, 4};
    EXPECT(triangulate(coordinates, holeStarts) == expected);
}


TEST(earcut_twoHoles) {
    std::vector<double> coordinates = {0.0, 0.0, 20.0, 0.0, 20.0, 10.0, 0.0, 10.0, 2.0, 2.0, 6.0, 2.0, 6.0, 8.0, 2.0, 8.0, 12.0, 2.0, 18.0, 2.0, 18.0, 8.0, 12.0, 8.0};
    std::vector<int> holeStarts = {4, 8};
    std::vector<int> expected = {5, 8, 11, 9, 4, 0, 3, 0, 4, 6, 5, 11, 9, 0, 1, 3, 4, 7, 10, 9, 1, 2, 3, 7, 10, 1, 2, 2, 7, 6, 11, 10, 2, 2, 6, 11};
    EXPECT(triangulate(coordinates, holeStarts) == expected);
}


TEST(earcut_threeHoles) {
    std::vector<double> coordinates = {0.0, 0.0, 30.0, 0.0, 30.0, 10.0, 0.0, 10.0, 2.0, 2.0, 6.0, 2.0, 6.0, 8.0, 2.0, 8.0, 12.0, 2.0, 16.0, 2.0, 16.0, 8.0, 12.0, 8.0, 22.0, 2.0, 28.0, 2.0, 28.0, 8.0, 22.0, 8.0};
    std::vector<int> holeStarts = {4, 8, 12};
    std::vector<int> expected = {9, 12, 15, 13, 4, 0, 3, 0, 4, 6, 5, 8, 10, 9, 15, 13, 0, 1, 3, 4, 7, 6, 8, 11, 14, 13, 1, 2, 3, 7, 14, 1, 2, 2, 7, 6, 15, 14, 2, 2, 6, 11, 10, 15, 2, 2, 11, 10};
    EXPECT(triangulate(coordinates, holeStarts) == expected);
}


